<template>
  <NConfigProvider :locale="zhCN" :date-locale="dateZhCN">
  <section class="risk-page" aria-label="风险排查" data-v2-inline-feedback>
    <header class="risk-toolbar" data-v2-navigation>
      <NButton v-if="detail||editor" :disabled="busy||!!pendingPublication" @click="back"><ArrowLeft :size="16" />排查列表</NButton>
      <NButton v-else-if="legacy" :disabled="busy" aria-label="返回" @click="navigate(scope?'/?entry=risk_inspection':'/?entry=risk')"><ArrowLeft :size="16" />返回</NButton>
      <strong>{{editor==='publish'?'发布风险排查':editor==='template'?'基础模板':editor==='history'?'历史模板库':detail?.name||'风险排查'}}</strong>
      <div class="risk-tools"><NButton v-if="editor!=='history'" :disabled="busy||unsaved||!!pendingPublication" :loading="loading" title="刷新" aria-label="刷新" @click="reload"><RefreshCw :size="16" /></NButton><template v-if="isManager&&!detail&&!editor"><NButton :disabled="busy||loading" @click="openEditor('template')"><Settings2 :size="16" />基础模板</NButton><NButton :disabled="busy||loading" @click="openEditor('history')"><Library :size="16" />历史模板库</NButton><NButton type="primary" :disabled="busy||loading" @click="openEditor('publish')"><Plus :size="16" />发布排查</NButton></template></div>
    </header>
    <NAlert v-if="error&&!confirmation&&!fieldEditor&&!feedbackOpen&&!pendingPublication" type="error" :bordered="false" role="alert">{{error}} <NButton v-if="detail" text :disabled="busy" @click="readLatest">重新读取，保留填写</NButton></NAlert>
    <NAlert v-if="message&&!feedbackOpen" type="info" :bordered="false" role="status">{{message}}</NAlert>
    <NSpin :show="loading">
      <RiskInspectionTemplateLibrary v-if="editor==='history'" ref="historyLibrary" @reuse="reuseHistory" />
      <template v-else-if="editor==='template'&&template">
        <div class="risk-section-heading"><div><strong>字段配置</strong><span>{{template.fields.length}} 列 · {{template.fields.filter((field:Dict)=>field.role==='input').length}} 列由排查人填写</span></div><NButton v-if="canEditTemplate" :disabled="busy||template.fields.length>=80" @click="editField()"><Plus :size="16" />添加字段</NButton></div>
        <NAlert v-if="template.fields.some((field:Dict)=>field.unsupported)" type="warning" :bordered="false">存在关联、公式或其它不支持复制的字段，调整后才可发布。</NAlert>
        <RiskInspectionSheet :fields="template.fields" schema :can-edit="canEditTemplate" :disabled="busy" @edit="editField" @remove-field="field=>ask('delete_field',field)" @required-change="changeRequired" />
        <p class="risk-note">必填字段在排查人提交时校验，发布预填和保存草稿可留空。修改仅用于后续发布，不改变已发布任务；删除字段会移除基础模板对应列的数据。</p>
      </template>
      <form v-else-if="editor==='publish'&&template" class="risk-publish" @submit.prevent="ask('publish')">
        <div class="risk-section-heading"><div><strong>发布信息</strong><NTag size="small" :bordered="false">{{publish.history_template_id?'历史模板：'+template.name+' · V'+template.revision:'基础模板'}}</NTag></div><NButton :disabled="publicationLocked" @click="openEditor('history')"><Library :size="16" />选择历史模板</NButton></div>
        <NAlert v-if="template.legacy" type="warning" :bordered="false">原任务未保留原始预填内容，已仅带入字段和事项标题，请核对补充。</NAlert>
        <div class="risk-fields"><label><span>排查表名 *</span><NInput v-model:value="publish.name" :disabled="publicationLocked" :maxlength="120" placeholder="例如：10月电气设备专项排查" :input-props="{'aria-label':'排查表名'}" /></label><label><span>反馈截止时间 *</span><NDatePicker v-model:value="publish.deadline" :disabled="publicationLocked" type="datetime" clearable :input-props="{'aria-label':'反馈截止时间'}" /></label><label><span>审核人 *</span><NSelect v-model:value="publish.reviewer_id" :disabled="publicationLocked" filterable :options="reviewerOptions" placeholder="选择有对应楼栋权限的审核人" aria-label="审核人" /></label><label><span>接收人员 *</span><NSelect v-model:value="selectedPeople" :disabled="publicationLocked" multiple filterable :max-tag-count="2" :options="peopleOptions" placeholder="搜索姓名或工号" aria-label="接收人员" /></label></div>
        <details v-if="selectedRows.length" class="risk-recipients"><summary><span>接收人员 {{selectedRows.length}} 人</span><span class="risk-scope-summary">{{recipientSummary}}</span><span>人员 / 楼栋</span></summary><div class="risk-recipient-editor"><div v-for="person in selectedRows" :key="person.id"><span>{{person.name}}<small>{{person.employee_no}}</small></span><NSelect :disabled="publicationLocked||person.scopes.length===1" :value="publish.people.find((p:Dict)=>p.id===person.id)?.scope" :options="person.scopes.map((s:string)=>({value:s,label:scopeLabel(s)}))" :aria-label="person.name+'的接收楼栋'" @update:value="s=>setScope(person.id,s)" /></div></div></details>
        <NAlert v-if="pendingPublication&&!busy" type="warning" :bordered="false" role="status" class="risk-publish-recovery"><strong>发布结果尚未确认，原内容已锁定保留。</strong><p v-if="error">{{error}}</p><div class="risk-tools"><NButton :disabled="busy" @click="checkPublication">核验本次发布</NButton><NButton :disabled="busy" @click="publishNow">按原内容重试</NButton></div></NAlert>
        <div class="risk-section-heading"><div><strong>排查事项</strong><span>{{publish.items.length}} 行 · {{template.fields.length}} 列</span></div><NButton :disabled="publicationLocked||publish.items.length>=100" @click="publish.items.push({title:'',values:{}})"><Plus :size="16" />添加事项</NButton></div>
        <RiskInspectionSheet :fields="template.fields" v-model:items="publish.items" :disabled="publicationLocked" />
        <footer class="risk-footer"><div><strong>{{selectedPeople.length}} 人 × {{publish.items.length}} 项</strong><span v-if="publishProblems.length&&!pendingPublication" class="risk-publish-missing">待补充：{{publishProblems.slice(0,3).join('；')}}{{publishProblems.length>3?' 等'+publishProblems.length+'项':''}}</span><span v-else class="risk-note">{{pendingPublication?'待核验本次发布':'每位接收人独立反馈，确认后创建结果表并发送通知'}}</span></div><NButton attr-type="submit" type="primary" :disabled="publicationLocked||!publishValid">确认发布</NButton></footer>
      </form>
      <div v-else-if="editor" class="risk-template-empty"><NEmpty v-if="!loading" description="模板或人员目录未完整读取，已阻止发布"><template #extra><NButton :disabled="busy" @click="reload">重新读取</NButton></template></NEmpty></div>
      <template v-else-if="detail">
        <div class="risk-toolbar risk-summary"><span>{{detail.owner}}发布 · 审核人 {{detail.reviewer}} · 截止 {{date(detail.deadline)}}</span><div class="risk-tools"><NButton v-if="detail.can_manage_release&&detail.status==='active'" size="small" :disabled="busy" @click="openReviewer">更换审核人</NButton><a v-if="detail.url" :href="detail.url" target="_blank" rel="noopener noreferrer">查看结果表 <ExternalLink :size="14" /></a></div></div>
        <NAlert v-if="detail.status!=='active'" type="warning" :bordered="false">正在创建排查表并登记链接，完成后自动发送邀请。请勿重复发布。</NAlert>
        <div v-if="incompleteJobs.length" class="risk-sync"><span>{{failedJobs.length?'部分云端操作未完成':'云端处理中'}} · {{incompleteJobs.length}} 项</span><NButton v-if="detail.can_manage_release&&failedJobs.some((j:Dict)=>j.status==='failed')" size="small" :disabled="busy" @click="ask('retry')">重试未完成操作</NButton><details v-if="failedJobs.length"><summary>查看原因</summary><p v-for="job in failedJobs" :key="job.id">{{jobLabel(job.kind)}}：{{job.error}}</p></details></div>
        <RiskInspectionTable :key="detail.id" :detail="detail" :busy="busy" @open="openFeedback" />
        <NDrawer :show="feedbackOpen" placement="right" width="min(760px, 100vw)" :mask-closable="!busy" :close-on-esc="!busy" @update:show="value=>{if(!value)closeFeedback()}">
          <NDrawerContent :title="person?person.name+' · '+scopeLabel(person.scope):'排查反馈'" :closable="!busy" class="risk-feedback-drawer" data-v2-inline-feedback>
          <main v-if="person" class="risk-feedback">
            <NAlert v-if="error&&!confirmation" type="error" :bordered="false" role="alert">{{error}} <NButton text :disabled="busy" @click="readLatest">重新读取，保留填写</NButton></NAlert>
            <NAlert v-if="message" type="info" :bordered="false" role="status">{{message}}</NAlert>
            <header class="risk-toolbar"><NTag :bordered="false">{{personProgress(person)}}</NTag><NButton v-if="detail.is_manager&&!person.revoked" type="error" size="small" quaternary :disabled="busy" @click="ask('revoke_person')">撤销该人员</NButton></header>
            <article v-for="item in focusedItems" :key="item.id" class="risk-response" :class="{revoked:item.status==='revoked'}">
              <header><strong>{{item.title}}</strong><NTag :type="item.status==='approved'?'success':item.status==='returned'?'warning':'default'" size="small">{{statusName(item.status)}}</NTag><NButton v-if="detail.is_manager&&!person.revoked&&item.status!=='revoked'" size="small" quaternary type="error" :disabled="busy" @click="ask('revoke_item',item)">撤销事项</NButton></header>
              <p v-if="item.reason" class="risk-note">{{item.status==='revoked'?'撤销原因':item.reviewed_by||'管理员'}}：{{item.reason}}</p>
              <RiskInspectionFields v-if="item.status!=='revoked'" :fields="detail.fields" :values="editable(item)?drafts[item.id]||item.values:item.values" :files="item.files" :disabled="!editable(item)||busy" @update:values="v=>drafts[item.id]=v" @files="(field,files)=>uploadFiles(item,field,files)" />
              <details v-if="drafts[item.id]&&!editable(item)" class="risk-local-draft"><summary>本地未提交内容（当前事项已变更）</summary><RiskInspectionFields :fields="detail.fields" :values="drafts[item.id]" :files="item.files" disabled /><NButton size="small" :disabled="busy" @click="discardDraft(item.id)">放弃这份本地填写</NButton></details>
              <footer><small>{{item.submitted_at?'提交于 '+date(item.submitted_at*1000):'尚未提交'}}{{item.reviewed_at?' · 审核于 '+date(item.reviewed_at*1000):''}}</small><div class="risk-tools"><template v-if="editable(item)"><NButton :disabled="busy" @click="act('save',item)">保存草稿</NButton><NButton type="primary" :disabled="busy" @click="ask('submit',item)">提交审核</NButton></template><template v-if="detail.is_reviewer&&item.status==='submitted'&&!person.revoked"><NButton :disabled="busy" @click="ask('return',item)">退回修改</NButton><NButton type="primary" :disabled="busy" @click="ask('approve',item)">审核通过</NButton></template></div></footer>
            </article>
          </main>
          <NEmpty v-else description="当前人员反馈已不在可访问范围，请关闭后重新选择。" />
          </NDrawerContent>
        </NDrawer>
        <details class="risk-audit"><summary>操作记录</summary><p v-for="(row,index) in detail.audit" :key="index">{{date(row.at*1000)}} · {{auditName(row)}} · {{actionName(row.action)}}</p></details>
      </template>
      <template v-else>
        <div class="risk-list-controls"><NInput v-model:value="taskSearch" clearable placeholder="搜索本页任务或审核人" :input-props="{'aria-label':'搜索排查任务'}"><template #prefix><Search :size="16" /></template></NInput><NSelect v-model:value="taskState" clearable :options="taskStateOptions" placeholder="全部状态" aria-label="排查任务状态" /><span>本页 {{filteredTasks.length}} / {{list.length}} 项</span></div>
        <div class="risk-task-list"><NDataTable :columns="taskColumns" :data="filteredTasks" :row-key="task=>task.id" :scroll-x="1050" size="small" :bordered="true" striped><template #empty><NEmpty :description="taskSearch||taskState?'本页没有符合条件的任务':'暂无分配的风险排查'"><template v-if="taskSearch||taskState" #extra><NButton @click="taskSearch='';taskState=null">清除筛选</NButton></template></NEmpty></template></NDataTable></div>
        <footer class="risk-list-footer"><span>共 {{total}} 个排查任务</span><NPagination v-if="total>20" :page="page" :page-count="Math.ceil(total/20)" :page-slot="5" @update:page="changePage" /></footer>
      </template>
    </NSpin>
    <NModal :show="!!fieldEditor" preset="card" title="模板字段" class="risk-modal" :mask-closable="false" :closable="!busy" :close-on-esc="!busy" @update:show="v=>{if(!v)closeFieldEditor()}"><NAlert v-if="error&&!confirmation" type="error" :bordered="false" role="alert">{{error}}</NAlert><div v-if="fieldEditor" class="risk-fields"><label><span>字段名称</span><NInput v-model:value="fieldEditor.field_name" :disabled="busy" :maxlength="80" :input-props="{'aria-label':'字段名称'}" /></label><label><span>字段类型</span><NSelect v-model:value="fieldEditor.type" :options="typeOptions" :disabled="busy||fieldEditor.is_primary" aria-label="字段类型" /></label><label><span>填写方式</span><NSelect v-model:value="fieldEditor.role" :disabled="busy" :options="roleOptions" aria-label="填写方式" /></label><label><span>填写要求</span><div v-if="fieldEditor.role==='input'" class="risk-required"><NSwitch v-model:value="fieldEditor.required" :disabled="busy" aria-label="字段是否必填" /><span>{{fieldEditor.required?'必填':'不必填'}}</span></div><small v-else>由系统自动填写，无需设置</small></label><label v-if="[3,4].includes(fieldEditor.type)" class="wide"><span>选项，每行一个</span><NInput v-model:value="fieldEditor.optionsText" :disabled="busy" type="textarea" :autosize="{minRows:3,maxRows:8}" /></label></div><template #footer><div class="risk-tools"><NButton :disabled="busy" @click="closeFieldEditor">取消</NButton><NButton type="primary" :disabled="busy||!fieldEditor?.field_name?.trim()" @click="ask('save_field')">保存字段</NButton></div></template></NModal>
    <NModal :show="!!confirmation" preset="card" :title="confirmTitle" class="risk-modal risk-confirm" :mask-closable="false" :close-on-esc="!busy" :closable="!busy" @update:show="v=>{if(!v&&!busy)confirmation=null}"><NAlert v-if="error" type="error" :bordered="false" role="alert">{{error}} <NButton v-if="detail" text :disabled="busy" @click="readLatest">重新读取，保留填写</NButton></NAlert><p>{{confirmText}}</p><dl v-if="confirmation?.action==='publish'" class="risk-confirm-summary"><dt>排查表名</dt><dd>{{publish.name}}</dd><dt>反馈截止</dt><dd>{{date(publish.deadline)}}</dd><dt>审核人</dt><dd>{{people.find((person:Dict)=>person.id===publish.reviewer_id)?.name}}</dd><dt>任务分配</dt><dd>{{selectedPeople.length}} 人 × {{publish.items.length}} 项 · {{recipientSummary}}</dd></dl><NSelect v-if="confirmation?.action==='reviewer'" v-model:value="newReviewer" :options="replacementOptions" :disabled="busy" filterable placeholder="选择新审核人" aria-label="新审核人" /><NInput v-if="needsReason" v-model:value="reason" :disabled="busy" type="textarea" :maxlength="2000" :autosize="{minRows:2,maxRows:4}" placeholder="请填写原因" /><template #footer><div class="risk-tools"><NButton :disabled="busy" @click="confirmation=null">取消</NButton><NButton type="primary" :loading="busy" :disabled="busy||needsReason&&!reason.trim()||confirmation?.action==='reviewer'&&!newReviewer" @click="confirm">确认</NButton></div></template></NModal>
  </section>
  </NConfigProvider>
</template>
<script setup lang="ts">
import {computed,h,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {NAlert,NButton,NConfigProvider,NDataTable,NDatePicker,NDrawer,NDrawerContent,NEmpty,NInput,NModal,NPagination,NSelect,NSpin,NSwitch,NTag,zhCN,dateZhCN,type DataTableColumns} from 'naive-ui';
import {ArrowLeft,ExternalLink,Library,Plus,RefreshCw,Search,Settings2} from 'lucide-vue-next';
import {ApiError,requestJson,type Dict} from '../api/client';
import {navigate,registerNavigationGuard} from '../navigation';
import RiskInspectionFields from './RiskInspectionFields.vue';
import RiskInspectionTemplateLibrary from './RiskInspectionTemplateLibrary.vue';
import RiskInspectionTable from './RiskInspectionTable.vue';
import RiskInspectionSheet from './RiskInspectionSheet.vue';
import {publicationIssues,reviewerIssue,riskRoles,riskTypeOptions} from './riskInspectionUi';
const props=defineProps<{releaseId?:string;scope?:string}>();
const legacy=!document.documentElement.classList.contains('workspace-v2');
const root='/api/risk-inspections';
const list=ref<Dict[]>([]),detail=ref<Dict|null>(null),template=ref<Dict|null>(null),people=ref<Dict[]>([]);
const page=ref(1),total=ref(0),isManager=ref(false),canEditTemplate=ref(false),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),editor=ref(''),personId=ref('');
const feedbackOpen=ref(false),focusedItemId=ref('');
const drafts=ref<Record<string,Dict>>({}),fieldEditor=ref<Dict|null>(null),confirmation=ref<Dict|null>(null),reason=ref(''),selectedPeople=ref<string[]>([]);
const publish=reactive<Dict>({id:'',name:'',deadline:null,reviewer_id:null,people:[],items:[{title:'',values:{}}],history_template_id:''});
const historyLibrary=ref<InstanceType<typeof RiskInspectionTemplateLibrary>|null>(null);
const pendingPublication=ref<Dict|null>(null),fieldOriginal=ref(''),taskSearch=ref(''),taskState=ref<string|null>(null);
const publicationLocked=computed(()=>busy.value||loading.value||!!pendingPublication.value);
const newReviewer=ref<string|null>(null);
const typeOptions=riskTypeOptions;
const roleOptions=Object.entries(riskRoles).map(([value,label])=>({value,label:value==='input'?label:'系统填写 · '+label}));
const peopleOptions=computed(()=>people.value.map(p=>({value:p.id,label:p.name+' · '+p.employee_no})));
const reviewerOptions=computed(()=>people.value.filter(p=>p.can_review).map(p=>{const issue=reviewerIssue(p,publish.people);return {value:p.id,label:p.name+' · '+p.scopes.map(scopeLabel).join('、')+(issue?'（'+issue+'）':''),disabled:!!issue};}));
const replacementOptions=computed(()=>people.value.filter(p=>p.can_review&&p.id!==detail.value?.reviewer_id&&detail.value?.people.every((assigned:Dict)=>p.scopes.includes(assigned.scope)&&(assigned.revoked||assigned.id!==p.id))).map(p=>({value:p.id,label:p.name+' · '+p.scopes.map(scopeLabel).join('、')})));
const selectedRows=computed(()=>people.value.filter(p=>selectedPeople.value.includes(p.id)));
const recipientSummary=computed(()=>{const scopes=new Map<string,number>();for(const person of publish.people)scopes.set(person.scope,(scopes.get(person.scope)||0)+1);return [...scopes].map(([scope,count])=>scopeLabel(scope)+' '+count+'人').join(' · ');});
watch(selectedPeople,ids=>{publish.people=ids.map(id=>{const existing=publish.people.find((p:Dict)=>p.id===id),person=people.value.find(p=>p.id===id);return existing||{id,scope:person?.scopes.includes(person.home_scope)?person.home_scope:person?.scopes[0]};});});
function setScope(id:string,scope:string){const p=publish.people.find((p:Dict)=>p.id===id);if(p)p.scope=scope;}
const person=computed(()=>detail.value?.people.find((p:Dict)=>p.id===personId.value));
const focusedItems=computed(()=>(person.value?.items||[]).filter((item:Dict)=>item.id===focusedItemId.value));
const taskStateOptions=[{value:'active',label:'进行中'},{value:'review',label:'待审核'},{value:'overdue',label:'已逾期'},{value:'completed',label:'已完成'},{value:'publishing',label:'发布处理中'}];
const filteredTasks=computed(()=>{const search=taskSearch.value.trim().toLocaleLowerCase();return list.value.filter(task=>(!search||[task.name,task.reviewer].join(' ').toLocaleLowerCase().includes(search))&&(!taskState.value||(taskState.value==='review'?task.submitted>task.approved:taskState.value==='overdue'?task.status==='active'&&task.total>task.approved&&task.deadline<Date.now():taskState.value==='completed'?task.total>0&&task.approved===task.total:taskState.value==='active'?task.status==='active'&&task.approved<task.total:task.status===taskState.value)));});
const taskColumns:DataTableColumns<Dict>=[
  {key:'name',title:'排查任务',width:310,render:task=>h(NButton,{text:true,disabled:busy.value,onClick:()=>openTask(task.id),'data-v2-navigation':true,class:'risk-task-name'},()=>task.name)},
  {key:'status',title:'状态',width:115,render:task=>h(NTag,{size:'small',bordered:false,type:task.total>0&&task.approved===task.total?'success':'default'},()=>task.status==='publishing'?'发布处理中':!task.total?'已撤销':task.approved===task.total?'已完成':'进行中')},
  {key:'people_count',title:'人员',width:80,render:task=>task.people_count+' 人'},
  {key:'progress',title:'反馈 / 总项数',width:120,render:task=>task.submitted+' / '+task.total},
  {key:'approved',title:'已通过',width:80},
  {key:'reviewer',title:'审核人',width:115},
  {key:'deadline',title:'反馈截止时间',width:190,render:task=>h('span',{class:task.deadline<Date.now()&&task.approved<task.total?'overdue':''},date(task.deadline))},
  {key:'action',title:'操作',width:100,fixed:'right',render:task=>h(NButton,{size:'small',disabled:busy.value,onClick:()=>openTask(task.id),'data-v2-navigation':true},()=> '查看反馈')},
];
const incompleteJobs=computed(()=>(detail.value?.jobs||[]).filter((j:Dict)=>j.status!=='done'));
const failedJobs=computed(()=>incompleteJobs.value.filter((j:Dict)=>j.error));
const dirty=computed(()=>Object.keys(drafts.value).some(id=>!sameValues(drafts.value[id],person.value?.items.find((i:Dict)=>i.id===id)?.values)));
const unsaved=computed(()=>dirty.value||!!pendingPublication.value||!!fieldEditor.value&&JSON.stringify(fieldEditor.value)!==fieldOriginal.value||editor.value==='publish'&&!!(publish.name||publish.deadline||publish.reviewer_id||selectedPeople.value.length||publish.items.some((i:Dict)=>i.title||Object.keys(i.values).length)));
const publishProblems=computed(()=>publicationIssues(publish,template.value?.fields||[],people.value));
const publishValid=computed(()=>!!template.value&&!publishProblems.value.length);
const needsReason=computed(()=>['return','revoke_item','revoke_person'].includes(confirmation.value?.action));
const confirmTitle=computed(()=>actionName(confirmation.value?.action||''));
const confirmText=computed(()=>confirmation.value?.action==='save_field'&&confirmation.value.item?`将「${confirmation.value.item.field_name}」设为${confirmation.value.item.required?'必填':'不必填'}，仅用于后续发布的排查，已发布任务不受影响。`:(({publish:'确认后将创建排查表并通知所选人员。',submit:'提交后不能继续编辑，审核人退回后可修改。',approve:'确认反馈内容已核实，通过后同步最终结果。',return:'反馈将退回本人修改，原提交记录保留。',revoke_item:'该人员不再需要完成此事项，已有反馈和操作记录保留。',revoke_person:'该人员不再需要完成本次排查，已有反馈和操作记录保留。',delete_field:'此操作会删除发布模板的字段及该列数据；不会修改已经发布的任务。',save_field:'字段修改用于后续发布。更改字段类型可能转换或清空模板原有数据。',reviewer:'已提交的反馈和原审核记录保留，尚未审核的事项将交由新审核人处理。',retry:'请先核对未完成原因。确认后以你的管理权限重试已保存的反馈，不改动原操作人和已填写内容。'} as Dict)[confirmation.value?.action||'']||''));
let read:AbortController|undefined,timer=0,disposed=false;
function beginWrite(){read?.abort();read=undefined;loading.value=false;busy.value=true;}
function date(v:number){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(v));}
function scopeLabel(v:string){return v==='110'?'110站':v+'楼';}
function statusName(v:string){return ({pending:'未提交',submitted:'待审核',approved:'审核通过',returned:'退回修改',revoked:'已撤销'} as Dict)[v]||v;}
function actionName(v:string){return ({save:'保存草稿',submit:'提交审核',approve:'审核通过',return:'退回修改',revoke_item:'撤销事项',revoke_person:'撤销人员',publish:'发布风险排查',delete_field:'删除模板字段',save_field:'保存模板字段',reviewer:'更换审核人',retry:'核对并重试同步'} as Dict)[v]||v;}
function jobLabel(v:string){return ({publish:'发布排查',notify:'消息通知',review_notice:'审核通知',sync:'结果落表',registry:'登记信息同步',template_sync:'历史模板备份'} as Dict)[v]||v;}
function auditName(row:Dict){try{return JSON.parse(row.data).name}catch{return '操作人'}}
function personProgress(p:Dict){const items=p.items.filter((i:Dict)=>i.status!=='revoked');return `反馈 ${items.filter((i:Dict)=>['submitted','approved'].includes(i.status)).length}/${items.length} · 通过 ${items.filter((i:Dict)=>i.status==='approved').length}`;}
function editable(item:Dict){return detail.value?.status==='active'&&!person.value?.revoked&&detail.value?.self_id===person.value?.id&&['pending','returned'].includes(item.status);}
function openFeedback(row:{person:Dict;item:Dict}){if(busy.value)return;if(dirty.value&&!window.confirm('有未保存内容，是否放弃并切换反馈？'))return;drafts.value={};personId.value=row.person.id;focusedItemId.value=row.item.id;feedbackOpen.value=true;error.value='';message.value='';}
function closeFeedback(){if(busy.value)return;if(dirty.value&&!window.confirm('有未保存内容，是否放弃并关闭？'))return;drafts.value={};feedbackOpen.value=false;}
function validateDetail(data:Dict){if(!data?.id||!Array.isArray(data.fields)||!Array.isArray(data.people)||data.people.some((person:Dict)=>!Array.isArray(person.items)))throw new Error('反馈记录未完整返回，已保留当前内容，请重新读取核对。');}
function applyDetail(data:Dict){validateDetail(data);detail.value=data;if(!feedbackOpen.value&&!data.people.some((p:Dict)=>p.id===personId.value))personId.value=data.people.find((p:Dict)=>p.id===data.self_id)?.id||data.people[0]?.id;}
async function reload(){
 if(editor.value==='history')return;
 if(busy.value||dirty.value)return;read?.abort();const abort=new AbortController();read=abort;loading.value=true;error.value='';
 try{if(editor.value){const mode=editor.value,path=mode==='publish'&&publish.history_template_id?'/templates/'+publish.history_template_id:'/template';template.value=null;const [data,directory]=await Promise.all([requestJson(root+path,{signal:abort.signal,cache:'no-store',timeoutMs:60000}),mode==='publish'?requestJson(root+'/people',{signal:abort.signal,cache:'no-store'}):Promise.resolve(null)]);if(!Array.isArray(data.fields)||!data.fields.length||!data.version||directory&&!Array.isArray(directory.items))throw new Error('模板或人员目录返回不完整，暂不能发布，请重新读取。');if(!abort.signal.aborted){template.value=data;if(directory)people.value=directory.items;}}
 else if(detail.value){const data=await requestJson(root+'/'+detail.value.id,{signal:abort.signal,cache:'no-store'});if(!abort.signal.aborted)applyDetail(data);}
 else {const data=await requestJson(root+'?page='+page.value+(props.scope?'&scope='+encodeURIComponent(props.scope):''),{signal:abort.signal,cache:'no-store'});if(!abort.signal.aborted){list.value=data.items;total.value=data.total;isManager.value=data.is_manager;canEditTemplate.value=data.can_edit_template;}}}
 catch(e:any){if(!abort.signal.aborted)error.value=e.message;}finally{if(read===abort){loading.value=false;read=undefined;}}
}
async function openTask(id:string){if(busy.value)return;read?.abort();const abort=new AbortController();read=abort;loading.value=true;error.value='';try{const d=await requestJson(root+'/'+encodeURIComponent(id),{signal:abort.signal,cache:'no-store'});if(!abort.signal.aborted)applyDetail(d);}catch(e:any){if(!abort.signal.aborted)error.value=e.message;}finally{if(read===abort){read=undefined;loading.value=false;}}}
function resetPublication(){selectedPeople.value=[];Object.assign(publish,{id:Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join(''),name:'',deadline:null,reviewer_id:null,people:[],items:[{title:'',values:{}}],history_template_id:''});}
async function openEditor(mode:string){if(busy.value||pendingPublication.value||unsaved.value&&!window.confirm('放弃当前未发布内容并切换模板来源？'))return;resetPublication();template.value=null;editor.value=mode;message.value='';error.value='';if(mode==='history')return;await reload();}
async function reuseHistory(data:Dict){beginWrite();error.value='';try{const directory=await requestJson(root+'/people',{cache:'no-store'});people.value=directory.items;resetPublication();template.value=data;Object.assign(publish,{name:data.name,items:structuredClone(data.items),history_template_id:data.id});editor.value='publish';message.value='已带入历史模板；请重新确认人员、审核人及截止时间。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function back(){if(busy.value||pendingPublication.value||editor.value==='history'&&historyLibrary.value&&!historyLibrary.value.leaveAllowed()||unsaved.value&&!window.confirm('放弃未保存的修改并返回列表？'))return;if(editor.value==='publish')resetPublication();feedbackOpen.value=false;detail.value=null;editor.value='';drafts.value={};message.value='';void reload();}
function changePage(value:number){page.value=value;taskSearch.value='';taskState.value=null;void reload();}
function editField(field?:Dict){fieldEditor.value=field?{...field,optionsText:(field.property?.options||[]).map((v:Dict)=>v.name).join('\n')}:{field_name:'',type:1,role:'input',required:false,optionsText:''};fieldOriginal.value=JSON.stringify(fieldEditor.value);}
function changeRequired(field:Dict,required:boolean){if(busy.value||!canEditTemplate.value||field.role!=='input'||field.unsupported)return;ask('save_field',{...field,required});}
function closeFieldEditor(){if(busy.value)return;if(fieldEditor.value&&JSON.stringify(fieldEditor.value)!==fieldOriginal.value&&!window.confirm('放弃尚未保存的字段修改？'))return;fieldEditor.value=null;}
function ask(action:string,item?:Dict){if(action==='publish'&&(!publishValid.value||pendingPublication.value)){error.value=publishProblems.value.length?'请补充：'+publishProblems.value.join('；'):'请先核验原发布结果。';return;}error.value='';reason.value='';confirmation.value={action,item,version:person.value?.version};}
async function openReviewer(){if(busy.value)return;beginWrite();error.value='';try{const data=await requestJson(root+'/people',{cache:'no-store'});people.value=data.items;newReviewer.value=null;confirmation.value={action:'reviewer',version:detail.value?.reviewer_version};}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function discardDraft(id:string){if(window.confirm('确认放弃此项尚未提交的本地填写？'))delete drafts.value[id];}
function sameValues(a:Dict|undefined,b:Dict|undefined){const keys=Object.keys(a||{}),other=Object.keys(b||{});return keys.length===other.length&&keys.every(k=>other.includes(k)&&JSON.stringify(a?.[k])===JSON.stringify(b?.[k]));}
async function readLatest(){if(busy.value||!detail.value)return;beginWrite();try{const data=await requestJson(root+'/'+detail.value.id,{cache:'no-store'});validateDetail(data);const current=data.people.find((p:Dict)=>p.id===personId.value);for(const item of current?.items||[])if(sameValues(drafts.value[item.id],item.values))delete drafts.value[item.id];applyDetail(data);confirmation.value=null;error.value='';message.value='已读取最新状态，未提交的填写仍保留，请核对后继续。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function act(action:string,item?:Dict,version=person.value?.version){
 if(busy.value||!detail.value||!person.value)return;beginWrite();error.value='';message.value='';
 try{const data=await requestJson(`${root}/${detail.value.id}/people/${person.value.id}/actions`,{method:'POST',body:JSON.stringify({action,version,item_id:item?.id,values:item?(drafts.value[item.id]||item.values):undefined,reason:reason.value})});applyDetail(data);if(item)delete drafts.value[item.id];message.value=action==='save'?'草稿已保存。':'操作已保存，云端结果正在同步。';confirmation.value=null;}
 catch(e:any){error.value=e.message;}finally{busy.value=false;}
}
async function confirm(){
 const c=confirmation.value;if(!c||busy.value)return;
 if(c.action==='publish'){await publishNow();return;}
 if(c.action==='retry'){await retry();return;}
 if(c.action==='reviewer'){beginWrite();error.value='';try{applyDetail(await requestJson(root+'/'+detail.value!.id+'/reviewer',{method:'POST',body:JSON.stringify({reviewer_id:newReviewer.value,version:c.version})}));confirmation.value=null;message.value='审核人已更换，待审核事项将通知新审核人。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}return;}
 if(!['save_field','delete_field'].includes(c.action)){await act(c.action,c.item,c.version);return;}
 beginWrite();error.value='';
 try{const f=c.action==='delete_field'?c.item:c.item||fieldEditor.value;const originalOptions=(f.property?.options||[]).map((option:Dict)=>option.name);const options=c.item||f.optionsText===originalOptions.join('\n')?originalOptions:(f.optionsText||'').split('\n').map((s:string)=>s.trim()).filter(Boolean);template.value=await requestJson(root+'/template',{method:'POST',body:JSON.stringify({action:c.action==='delete_field'?'delete':f.key?'update':'add',version:template.value?.version,field_id:f.key,field_name:f.field_name,type:f.type,role:f.role,required:f.required,options,confirmed:true}),timeoutMs:60000});fieldEditor.value=null;message.value='模板已保存，已发布任务不受影响。';
 confirmation.value=null;
 }catch(e:any){error.value=e.message;}finally{busy.value=false;}
}
function publicationAccepted(data:Dict){applyDetail(data);pendingPublication.value=null;confirmation.value=null;editor.value='';resetPublication();error.value='';message.value='发布已受理，创建排查表后自动发送通知。';}
async function resolvePublication(){const id=pendingPublication.value?.id;if(!id)return false;try{const data=await requestJson(root+'/'+encodeURIComponent(id),{cache:'no-store'});if(data.id!==id)return false;publicationAccepted(data);return true;}catch{return false;}}
async function checkPublication(){if(busy.value||!pendingPublication.value)return;beginWrite();try{if(!await resolvePublication())error.value='尚未核实本次发布。原内容和发布标识已保留，可按原内容重试，请勿重新发布。';}finally{busy.value=false;}}
async function publishNow(){
 if(busy.value)return;
 if(!pendingPublication.value){const issues=publicationIssues(publish,template.value?.fields||[],people.value);if(!template.value||issues.length){error.value='请补充：'+issues.join('；');return;}pendingPublication.value=JSON.parse(JSON.stringify({...publish,template_version:template.value.version}));}
 beginWrite();error.value='';
 try{publicationAccepted(await requestJson(root,{method:'POST',body:JSON.stringify(pendingPublication.value),timeoutMs:60000}));}
 catch(e:any){
  if(e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==408){pendingPublication.value=null;error.value=e.message;}
  else if(!await resolvePublication()){confirmation.value=null;error.value=e.message+'；发布结果尚未确认，已保留原发布标识。';}
 }finally{busy.value=false;}
}
async function uploadFiles(item:Dict,field:string,files:File[]){if(busy.value||!editable(item))return;error.value='';const invalid=files.find(file=>!file.size||file.size>20*1024*1024||! /\.(pdf|docx?|xlsx?|xlsm|md|txt|csv|jpe?g|png|webp)$/i.test(file.name));if(invalid){error.value=invalid.name+'：请选择20MB以内的非空照片、办公文件或文本文件。';return;}if(((drafts.value[item.id]||item.values)[field]||[]).length+files.length>20){error.value='每个附件字段最多保留20个文件，请先移除不需要的附件。';return;}beginWrite();try{for(const file of files){const q=new URLSearchParams({name:file.name,item_id:item.id,field_id:field});const saved=await requestJson(`${root}/${detail.value!.id}/files?${q}`,{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'},timeoutMs:120000});item.files.push(saved);const current=drafts.value[item.id]||item.values;drafts.value[item.id]={...current,[field]:[...(current[field]||[]),saved.id]};}}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function retry(){if(busy.value||!detail.value)return;beginWrite();error.value='';try{applyDetail(await requestJson(root+'/'+detail.value.id+'/retry',{method:'POST',body:'{}'}));confirmation.value=null;message.value='已安排重试，原操作人和反馈内容保持不变。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
function leaving(e:BeforeUnloadEvent){if(unsaved.value||busy.value){e.preventDefault();e.returnValue='';}}
const unregister=registerNavigationGuard(()=>!busy.value&&(editor.value==='history'?historyLibrary.value?.leaveAllowed()!==false:!unsaved.value||window.confirm('有未保存内容，是否放弃并离开？')));
onMounted(async()=>{await reload();if(disposed)return;if(props.releaseId)await openTask(props.releaseId);if(disposed)return;window.addEventListener('beforeunload',leaving);timer=window.setInterval(()=>{const editing=document.activeElement?.closest('.risk-page input,.risk-page textarea,.risk-feedback input,.risk-feedback textarea,[role="listbox"]');if(!disposed&&!document.hidden&&!busy.value&&!dirty.value&&!editor.value&&!confirmation.value&&!fieldEditor.value&&!editing)void reload();},15000);});
onBeforeUnmount(()=>{disposed=true;read?.abort();unregister();window.clearInterval(timer);window.removeEventListener('beforeunload',leaving);});
</script>
